"""Stable Python source identities for generated artifacts."""

from __future__ import annotations

import ast
import io
from pathlib import Path
import tokenize
from typing import Iterable


def semantic_python_source_bytes(path: Path) -> bytes:
    """Return normalized Python source with lexical comments removed."""

    source = path.read_bytes().replace(b"\r\n", b"\n").replace(b"\r", b"\n")
    encoding, _lines = tokenize.detect_encoding(io.BytesIO(source).readline)
    text = source.decode(encoding)
    lines = text.splitlines()
    removed_lines = set()
    for token in tokenize.generate_tokens(io.StringIO(text).readline):
        if token.type != tokenize.COMMENT:
            continue
        line_index = int(token.start[0]) - 1
        prefix = lines[line_index][: int(token.start[1])]
        if prefix.strip():
            lines[line_index] = prefix.rstrip()
        else:
            removed_lines.add(line_index)
    payload = "\n".join(
        line.rstrip()
        for index, line in enumerate(lines)
        if index not in removed_lines
    )
    return payload.encode("utf-8")


def semantic_python_symbols_bytes(
    path: Path,
    symbols: Iterable[str],
) -> bytes:
    """Return a token-normalized identity for selected top-level symbols."""

    requested = tuple(symbols)
    if not requested or len(set(requested)) != len(requested):
        raise ValueError("Python source identity symbols must be unique")
    tree = ast.parse(path.read_bytes(), filename=str(path))
    definitions = {
        node.name: node
        for node in tree.body
        if isinstance(node, (ast.AsyncFunctionDef, ast.ClassDef, ast.FunctionDef))
    }
    missing = [name for name in requested if name not in definitions]
    if missing:
        raise ValueError(f"Python source identity symbols are missing: {missing}")
    source_lines = path.read_text(encoding="utf-8").splitlines()
    payload: list[str] = []
    for name in requested:
        node = definitions[name]
        decorators = getattr(node, "decorator_list", ())
        start_line = min(
            (node.lineno, *(decorator.lineno for decorator in decorators))
        )
        segment = "\n".join(source_lines[start_line - 1 : node.end_lineno])
        for token in tokenize.generate_tokens(io.StringIO(segment).readline):
            if token.type in (tokenize.COMMENT, tokenize.ENDMARKER, tokenize.NL):
                continue
            token_name = tokenize.tok_name[token.type]
            if token.type in (tokenize.DEDENT, tokenize.INDENT, tokenize.NEWLINE):
                payload.append(token_name)
            else:
                payload.append(f"{token_name}:{token.string}")
    return "\0".join(payload).encode("utf-8")


def _semantic_node_tokens(source_lines: list[str], node: ast.AST) -> str:
    decorators = getattr(node, "decorator_list", ())
    start_line = min(
        (node.lineno, *(decorator.lineno for decorator in decorators))
    )
    segment = "\n".join(source_lines[start_line - 1 : node.end_lineno])
    payload = []
    for token in tokenize.generate_tokens(io.StringIO(segment).readline):
        if token.type in (tokenize.COMMENT, tokenize.ENDMARKER, tokenize.NL):
            continue
        token_name = tokenize.tok_name[token.type]
        if token.type in (tokenize.DEDENT, tokenize.INDENT, tokenize.NEWLINE):
            payload.append(token_name)
        else:
            payload.append(f"{token_name}:{token.string}")
    return "\0".join(payload)


def _definition_names(node: ast.AST) -> tuple[str, ...]:
    if isinstance(node, (ast.AsyncFunctionDef, ast.ClassDef, ast.FunctionDef)):
        return (node.name,)
    if isinstance(node, (ast.Assign, ast.AnnAssign)):
        targets = node.targets if isinstance(node, ast.Assign) else (node.target,)
        return tuple(
            target.id for target in targets if isinstance(target, ast.Name)
        )
    return ()


def semantic_python_symbol_closure_source_bytes(
    source: str,
    symbols: Iterable[str],
    *,
    exclude: Iterable[str] = (),
) -> bytes:
    """Return normalized selected symbols and their local dependencies.

    Qualified roots select individual class members (for example,
    ``CubinFamily.resolve_dispatch``). References to other top-level symbols
    and same-class members are followed transitively. Comments, formatting,
    unrelated functions, and unrelated class members are outside the identity.
    """

    requested = tuple(symbols)
    excluded_values = tuple(exclude)
    excluded = frozenset(excluded_values)
    if (
        not requested
        or len(set(requested)) != len(requested)
        or len(excluded) != len(excluded_values)
    ):
        raise ValueError("Python source identity symbols must be unique")
    tree = ast.parse(source)
    top_level = {
        name: node
        for node in tree.body
        for name in _definition_names(node)
    }
    class_members = {
        class_name: {
            name: member
            for member in class_node.body
            for name in _definition_names(member)
        }
        for class_name, class_node in top_level.items()
        if isinstance(class_node, ast.ClassDef)
    }

    def resolve(name: str) -> tuple[str | None, ast.AST]:
        owner, separator, member = name.partition(".")
        if not separator:
            node = top_level.get(owner)
            if node is None:
                raise ValueError(
                    f"Python source identity symbols are missing: {[name]}"
                )
            return None, node
        node = class_members.get(owner, {}).get(member)
        if node is None or "." in member:
            raise ValueError(
                f"Python source identity symbols are missing: {[name]}"
            )
        return owner, node

    for name in (*requested, *excluded):
        resolve(name)

    pending = list(requested)
    selected: dict[str, tuple[str | None, ast.AST]] = {}
    while pending:
        name = pending.pop()
        if name in selected or name in excluded:
            continue
        owner, node = resolve(name)
        selected[name] = (owner, node)
        for reference in ast.walk(node):
            dependency = None
            if (
                owner is not None
                and isinstance(reference, ast.Attribute)
                and isinstance(reference.value, ast.Name)
                and reference.value.id in {"self", "cls", owner}
                and reference.attr in class_members[owner]
            ):
                dependency = f"{owner}.{reference.attr}"
            elif (
                isinstance(reference, ast.Name)
                and isinstance(reference.ctx, ast.Load)
                and reference.id in top_level
                and reference.id != owner
            ):
                dependency = reference.id
            if (
                dependency is not None
                and dependency not in selected
                and dependency not in excluded
            ):
                pending.append(dependency)

    source_lines = source.splitlines()
    payload = [
        f"{name}\0{_semantic_node_tokens(source_lines, node)}"
        for name, (_owner, node) in sorted(selected.items())
    ]
    return "\0\0".join(payload).encode("utf-8")


def semantic_python_symbol_closure_bytes(
    path: Path,
    symbols: Iterable[str],
    *,
    exclude: Iterable[str] = (),
) -> bytes:
    """Read ``path`` and return its selected semantic dependency closure."""

    return semantic_python_symbol_closure_source_bytes(
        path.read_text(encoding="utf-8"), symbols, exclude=exclude
    )
